// Starter project generated by `orosmo init`: a lit cube turned by the game logic (src/game/) and a HUD (src/HudView.cui).
// `orosmo::app::Application` owns the window, the device (Vulkan, falling back to OpenGL), the renderers, the interface and the
// loop; `--help` lists the options (--api, --headless, --capture...). Development build (`make debug`): rebuilding src/game/
// reloads the game logic, saving a .cui rebuilds the HUD (an error keeps the previous HUD and is shown at the top right).
#include "HudView.gen.h"
#include "game/spin.hpp"
#include "hud_state.hpp"

#include <orosmo/app/default_game.hpp>
#include <orosmo/platform/window.hpp>

#include <array>

namespace app = orosmo::app;

int main(int argc, char **argv)
{
    HudState state; // bound by the HUD: declared before the application, destroyed after it
    return app::Application::main(argc, argv, app::defaultSettings("{{PROJECT_NAME}}"), [&state](app::Application &a) -> orosmo::core::Result<> {
        const std::array<glm::vec4, 6> faces{{{0.86f, 0.48f, 0.26f, 1}, {0.72f, 0.36f, 0.22f, 1}, {0.38f, 0.76f, 0.44f, 1},
                                              {0.30f, 0.52f, 0.34f, 1}, {0.25f, 0.58f, 0.88f, 1}, {0.20f, 0.45f, 0.72f, 1}}};
        auto mesh = a.addMesh(orosmo::renderer::MeshBuilder(orosmo::renderer::MeshLayout::kColored).addBox({1, 1, 1}, faces));
        if (!mesh)
            return std::unexpected(mesh.error());
        const orosmo::scene::Entity cube = a.spawn(app::MeshRenderer{.mesh = *mesh});
        if (auto spin = a.world().componentType<game::Spin>("Spin")) // registered by the game logic, which turns the cube
            a.world().add(cube, *spin, game::Spin{});
        a.spawn(app::LightComponent{.type = orosmo::renderer::LightType::kAmbient, .intensity = 0.35f});
        a.spawn(app::LightComponent{.color = {1.0f, 0.96f, 0.90f}, .intensity = 0.85f, .direction = {-0.6f, -0.8f, -0.5f}});

        a.onUpdate([&state](app::Application &a, const app::FrameTime &) {
            ++state.frame;
            a.pauseSimulation(!state.rotate); // "Rotate cube" checkbox
            if (a.window() != nullptr && a.window()->input().isKeyJustPressed(orosmo::platform::KeyButton::kEscape))
                a.quit();
        });
        return a.setView(cui::HudView{.state = &state});
    });
}
